    function __ESBMC_assume(bool) internal pure {}

    function run(address tokenAddress, address tokenOwner, uint256 tokens) public payable {
        uint256 beforeEthBalance = address(c).balance;

        bool success;
        bool r = c.transferAnyERC20Token(tokenAddress, tokenOwner, tokens); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            success = false;
        } else {
            success = r;
        }

        uint256 afterEthBalance = address(c).balance;

        assert(afterEthBalance == beforeEthBalance);
    }

    receive() external payable {}
