        c = new PoCGame(address(this), 0);
    }

    function _run(address tokenAddress, address tokenOwner, uint256 tokens) internal {
        uint256 beforeEthBalance = address(c).balance;
        bool success;
        try c.transferAnyERC20Token(tokenAddress, tokenOwner, tokens) returns (bool r) {
            success = r;
        } catch {
            success = false;
        }
        uint256 afterEthBalance = address(c).balance;
        assertTrue(afterEthBalance == beforeEthBalance);
    }

